import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import SignupForm from '../components/signup/SignupForm';
import { Link } from 'react-router-dom';
import SignupVisual from '../components/signup/SignupVisual';

const Signup = () => {
    return (
        <div className="bg-background text-on-background min-h-screen flex flex-col">
            <Header />

            {/* Main Content */}
            <main className="flex-grow flex items-center justify-center px-4 md:px-8 pt-24 pb-12 w-full">
                <div className="w-full max-w-[1100px] flex flex-col md:flex-row gap-8 lg:gap-16 items-center justify-center mx-auto">
                    {/* Visual Section */}
                    <div className="w-full md:w-1/2 h-[650px] rounded-[24px] overflow-hidden shadow-xl border border-black/5 dark:border-white/5">
                        <SignupVisual />
                    </div>

                    {/* Form Section */}
                    <div className="w-full md:w-1/2 max-w-[440px] flex flex-col">
                        <SignupForm />
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Signup;
